#include "main.h"
static void SystemClock_Config(void); static void MX_GPIO_Init(void);
int main(void) { HAL_Init(); SystemClock_Config(); MX_GPIO_Init(); uint32_t started=0,last_blink=0; uint8_t pressed=0,handled=0,blink=0; while (1) { GPIO_PinState key=HAL_GPIO_ReadPin(GPIOC,GPIO_PIN_13); if(key==GPIO_PIN_SET&&!pressed){HAL_Delay(25);if(HAL_GPIO_ReadPin(GPIOC,GPIO_PIN_13)==GPIO_PIN_SET){pressed=1;handled=0;started=HAL_GetTick();}} if(pressed&&key==GPIO_PIN_SET&&!handled&&HAL_GetTick()-started>=1000){blink=1;handled=1;last_blink=HAL_GetTick();} if(pressed&&key==GPIO_PIN_RESET){uint32_t duration=HAL_GetTick()-started;pressed=0;if(duration<1000){if(blink)blink=0;else HAL_GPIO_TogglePin(GPIOA,GPIO_PIN_5);}} if(blink && HAL_GetTick()-last_blink>=250){HAL_GPIO_TogglePin(GPIOA,GPIO_PIN_5);last_blink=HAL_GetTick();} } }
